Here is a complete, playable **"Emoji Memory Match"** game. You can copy and paste this code into a single HTML file (e.g., `memory-game.html`) and open it in any web browser to play.

### The Game: Cosmic Memory
**Goal:** Find all matching pairs of emojis. The fewer swaps you make, the higher your score!

```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Cosmic Memory Match</title>
    <style>
        :root {
            --bg-color: #1a1a2e;
            --card-bg: #16213e;
            --card-back: #0f3460;
            --accent: #e94560;
            --text: #ffffff;
        }

        body {
            font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
            background-color: var(--bg-color);
            color: var(--text);
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            min-height: 100vh;
            margin: 0;
        }

        h1 {
            margin-bottom: 10px;
            font-size: 2.5rem;
            text-shadow: 2px 2px var(--accent);
        }

        .stats {
            display: flex;
            gap: 20px;
            margin-bottom: 20px;
            font-size: 1.2rem;
        }

        .grid {
            display: grid;
            grid-template-columns: repeat(4, 1fr);
            gap: 15px;
            perspective: 1000px;
        }

        .card {
            width: 80px;
            height: 80px;
            position: relative;
            cursor: pointer;
            transform-style: preserve-3d;
            transition: transform 0.5s;
        }

        .card.flipped {
            transform: rotateY(180deg);
        }

        .card.matched {
            cursor: default;
            animation: pulse 0.5s ease-in-out;
        }

        .card-face {
            width: 100%;
            height: 100%;
            position: absolute;
            backface-visibility: hidden;
            display: flex;
            align-items: center;
            justify-content: center;
            border-radius: 10px;
            font-size: 2.5rem;
            user-select: none;
            box-shadow: 0 4px 6px rgba(0,0,0,0.3);
        }

        .card-front {
            background-color: var(--card-back);
            border: 2px solid var(--accent);
        }

        .card-back {
            background-color: var(--card-bg);
            transform: rotateY(180deg);
        }

        button {
            margin-top: 25px;
            padding: 10px 20px;
            font-size: 1.2rem;
            background-color: var(--accent);
            color: white;
            border: none;
            border-radius: 5px;
            cursor: pointer;
            transition: background 0.3s;
        }

        button:hover {
            background-color: #c0394d;
        }

        @keyframes pulse {
            0% { transform: rotateY(180deg) scale(1); }
            50% { transform: rotateY(180deg) scale(1.1); box-shadow: 0 0 15px var(--accent); }
            100% { transform: rotateY(180deg) scale(1); }
        }

        /* Mobile Responsiveness */
        @media (max-width: 500px) {
            .grid { grid-template-columns: repeat(4, 1fr); gap: 10px; }
            .card { width: 60px; height: 60px; }
            .card-face { font-size: 1.8rem; }
        }
    </style>
</head>
<body>

    <h1>Cosmic Memory</h1>

    <div class="stats">
        <span>Moves: <span id="moves">0</span></span>
        <span>Pairs: <span id="pairs">0</span>/8</span>
    </div>

    <div class="grid" id="gameGrid">
        <!-- Cards generated by JS -->
    </div>

    <button onclick="restartGame()">Restart Game</button>

    <script>
        const emojis = ['🚀', '🛸', '🌑', '⭐', '🪐', '👽', '☄️', '👾'];
        let cards = [];
        let hasFlippedCard = false;
        let lockBoard = false;
        let firstCard, secondCard;
        let moves = 0;
        let pairsFound = 0;

        const grid = document.getElementById('gameGrid');
        const movesDisplay = document.getElementById('moves');
        const pairsDisplay = document.getElementById('pairs');

        function initGame() {
            // Duplicate emojis to create pairs
            cards = [...emojis, ...emojis];
            // Shuffle
            cards.sort(() => 0.5 - Math.random());

            // Clear board
            grid.innerHTML = '';
            moves = 0;
            pairsFound = 0;
            updateStats();

            // Create HTML for cards
            cards.forEach(emoji => {
                const card = document.createElement('div');
                card.classList.add('card');
                card.innerHTML = `
                    <div class="card-face card-front">?</div>
                    <div class="card-face card-back">${emoji}</div>
                `;
                card.addEventListener('click', flipCard);
                grid.appendChild(card);
            });
        }

        function flipCard() {
            if (lockBoard) return;
            if (this === firstCard) return; // Prevent double clicking same card

            this.classList.add('flipped');

            if (!hasFlippedCard) {
                // First click
                hasFlippedCard = true;
                firstCard = this;
                return;
            }

            // Second click
            secondCard = this;
            incrementMoves();
            checkForMatch();
        }

        function checkForMatch() {
            let isMatch = firstCard.innerHTML === secondCard.innerHTML;

            isMatch ? disableCards() : unflipCards();
        }

        function disableCards() {
            firstCard.classList.add('matched');
            secondCard.classList.add('matched');

            pairsFound++;
            updateStats();
            resetBoard();

            if (pairsFound === emojis.length) {
                setTimeout(() => alert(`🎉 You won in ${moves} moves!`), 500);
            }
        }

        function unflipCards() {
            lockBoard = true;
            setTimeout(() => {
                firstCard.classList.remove('flipped');
                secondCard.classList.remove('flipped');
                resetBoard();
            }, 1000);
        }

        function resetBoard() {
            [hasFlippedCard, lockBoard] = [false, false];
            [firstCard, secondCard] = [null, null];
        }

        function incrementMoves() {
            moves++;
            updateStats();
        }

        function updateStats() {
            movesDisplay.innerText = moves;
            pairsDisplay.innerText = pairsFound;
        }

        function restartGame() {
            initGame();
        }

        // Start the game on load
        initGame();
    </script>
</body>
</html>
```

### How to Play
1.  **Save the code:** Copy the code above and save it as an `.html` file (e.g., `game.html`).
2.  **Open it:** Double-click the file to open it in Chrome, Firefox, Safari, or Edge.
3.  **The Rules:**
    *   Click a card to flip it.
    *   Click a second card to find its partner.
    *   If they match, they stay open.
    *   If they don't match, they flip back over after 1 second.
    *   Try to clear the board in as few moves as possible!

### Features
*   **3D Animation:** The cards use CSS transforms to flip realistically.
*   **Responsive:** Works on desktop with a mouse and on mobile phones with touch.
*   **Score Tracking:** Keeps track of your moves and completed pairs in real-time.

